from pathlib import Path
import requests
urls = {
    'main': 'https://raw.githubusercontent.com/vertical-cloud-lab/custom-induction-furnace/c149c59/real_person_paper.pdf',
    'si': 'https://raw.githubusercontent.com/vertical-cloud-lab/custom-induction-furnace/c149c59/paper/SI.pdf'
}
headers={'User-Agent':'Mozilla/5.0 manuscript-verification'}
for name, url in urls.items():
    r = requests.get(url, headers=headers, allow_redirects=True, timeout=120)
    r.raise_for_status()
    out = Path('/workspace') / ('real_person_paper.pdf' if name=='main' else 'SI.pdf')
    out.write_bytes(r.content)
    print(name, out, len(r.content), r.headers.get('content-type'))

from e14c.web import web_search
queries = [
    'site:ni.com USB-6000 specifications analog output',
    'site:ni.com NI-9265 current output module specifications',
    'site:ni.com NI-9203 current input module specifications',
    'site:ni.com cDAQ-9174 USB chassis specifications',
    'LumaSense IMPAC ISR 6 manual 800 2500 dual wavelength ratio pyrometer'
]
results = {}
for q in queries:
    results[q] = await web_search(q, num_results=5)
    print('\nQUERY', q)
    for x in results[q][:3]: print(x.get('title'), x.get('url'), '\n', x.get('snippet','')[:500])

import requests
for url in ['https://doi.org/10.5281/zenodo.20878017','https://zenodo.org/records/20878017']:
