# Fetch source references.bib and tex to verify exact typos/placeholders
base='https://raw.githubusercontent.com/vertical-cloud-lab/custom-induction-furnace/c149c59/'
for f in ['paper/references.bib','paper/real_person_paper.tex','paper/SI.tex']:
    r=requests.get(base+f,timeout=30); print(f,r.status_code,len(r.text));
    if r.ok:
        for needle in ['Unknown journal','provisional','20878017','assembl']:
            if needle.lower() in r.text.lower():
                print(' ',needle,[line for line in r.text.splitlines() if needle.lower() in line.lower()][:4])

import requests,re,hashlib
base='https://raw.githubusercontent.com/vertical-cloud-lab/custom-induction-furnace/c149c59/'
# inspect source context around figure paths and try cited provenance files
src=requests.get(base+'paper/real_person_paper.tex',timeout=30).text
for i,l in enumerate(src.splitlines(),1):
    if any(k in l.lower() for k in ['kikuchi_raw','reg1a_x4100y1628','fig_kikuchi']):
        print(i,l)
# likely paths from source and repository conventions
candidates=['paper/figures/fig_kikuchi_raw.jpg','docs/SEM/reg1a_x4100y1628.jpg','docs/SEM/Ni_003b1a/reg1a_x4100y1628.jpg','paper/figures/reg1a_x4100y1628.jpg']
blobs={}
for p in candidates:
    r=requests.get(base+p,timeout=30)
    print(r.status_code,p,len(r.content))
    if r.ok: blobs[p]=r.content; print(hashlib.sha256(r.content).hexdigest())
